def clamp(value, lower, upper):
    if lower > upper:
        raise ValueError("lower must not exceed upper")
    return max(lower, min(value, upper))

function clamp(value, lower, upper) {
  if (lower > upper) {
    throw new RangeError('lower must not exceed upper')
  }
  return Math.max(lower, Math.min(value, upper))
}

def fizz_buzz(limit):
    result = []
    for number in range(1, limit + 1):
        if number % 15 == 0:
            result.append("FizzBuzz")
        elif number % 3 == 0:
            result.append("Fizz")
        elif number % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(number))
    return result

function fizzBuzz(limit) {
  const result = []
  for (let number = 1; number <= limit; number++) {
    if (number % 15 === 0) result.push('FizzBuzz')
    else if (number % 3 === 0) result.push('Fizz')
    else if (number % 5 === 0) result.push('Buzz')
    else result.push(String(number))
  }
  return result
}

def sum_range(start, end):
    if start > end:
        start, end = end, start
    total = 0
    for number in range(start, end + 1):
        total += number
    return total

function sumRange(start, end) {
  if (start > end) [start, end] = [end, start]
  let total = 0
  for (let number = start; number <= end; number++) {
    total += number
  }
  return total
}

def group_by_parity(numbers):
    groups = {"even": [], "odd": []}
    for number in numbers:
        key = "even" if number % 2 == 0 else "odd"
        groups[key].append(number)
    return groups

function groupByParity(numbers) {
  const groups = { even: [], odd: [] }
  for (const number of numbers) {
    const key = number % 2 === 0 ? 'even' : 'odd'
    groups[key].push(number)
  }
  return groups
}

def chunk_list(items, size):
    if size <= 0:
        raise ValueError("size must be positive")
    chunks = []
    for index in range(0, len(items), size):
        chunks.append(items[index:index + size])
    return chunks

function chunkArray(items, size) {
  if (size <= 0) throw new RangeError('size must be positive')
  const chunks = []
  for (let index = 0; index < items.length; index += size) {
    chunks.push(items.slice(index, index + size))
  }
  return chunks
}
